function usePrefersReducedMotion() {
    const [reducedMotion, setReducedMotion] = React.useState(false)

    React.useEffect(() => {
        if (typeof window === "undefined" || !window.matchMedia) return

        const query = window.matchMedia("(prefers-reduced-motion: reduce)")
        const update = () => setReducedMotion(query.matches)
        update()
        query.addEventListener?.("change", update)

        return () => query.removeEventListener?.("change", update)
    }, [])

    return reducedMotion
}

function colorWithOpacity(color: string, opacity: number) {
    const alpha = Math.max(0, Math.min(1, opacity))
    const value = color.trim()

    const shortHex = /^#([\da-f])([\da-f])([\da-f])$/i.exec(value)
    if (shortHex) {
        const [, r, g, b] = shortHex
        return `rgba(${parseInt(r + r, 16)}, ${parseInt(g + g, 16)}, ${parseInt(
            b + b,
            16
        )}, ${alpha})`
    }

    const longHex =
        /^#([\da-f]{2})([\da-f]{2})([\da-f]{2})(?:[\da-f]{2})?$/i.exec(value)
    if (longHex) {
        return `rgba(${parseInt(longHex[1], 16)}, ${parseInt(
            longHex[2],
            16
        )}, ${parseInt(longHex[3], 16)}, ${alpha})`
    }

    const rgb = /^rgba?\(\s*([\d.]+)\s*[, ]\s*([\d.]+)\s*[, ]\s*([\d.]+)/i.exec(
        value
    )
    if (rgb) {
        return `rgba(${rgb[1]}, ${rgb[2]}, ${rgb[3]}, ${alpha})`
    }

    return `color-mix(in srgb, ${value} ${alpha * 100}%, transparent)`
}

export default function TravingatBadge(props: TravingatBadgeProps) {
    const {
        outerRotationDuration = 18,
        innerRotationDuration = 10,
        outerRotationEnabled = true,
        innerRotationEnabled = true,
        startOnHoverOnly = false,
        blurAmount = 14,
        glassTint = "#080A0F",
        glassOpacity = 0.18,
        style,
    } = props

    const [isHovered, setIsHovered] = React.useState(false)
    const reducedMotion = usePrefersReducedMotion()
    const instanceId = React.useId().replace(/:/g, "")
    const outerKeyframes = `travingat-outer-spin-${instanceId}`
    const innerKeyframes = `travingat-inner-spin-${instanceId}`
    const selector = `[data-travingat-badge="${instanceId}"]`
    const playState =
        startOnHoverOnly && !isHovered
            ? ("paused" as const)
            : ("running" as const)

    const outerAnimation =
        outerRotationEnabled && !reducedMotion
            ? `${outerKeyframes} ${Math.max(
                  1,
                  outerRotationDuration
              )}s linear infinite`
            : "none"

    const innerAnimation =
        innerRotationEnabled && !reducedMotion
            ? `${innerKeyframes} ${Math.max(
                  1,
                  innerRotationDuration
              )}s linear infinite`
            : "none"

    return (
        <div
            data-travingat-badge={instanceId}
            style={{
                position: "relative",
                width: "100%",
                height: "100%",
                display: "block",
                padding: 0,
                margin: 0,
                aspectRatio: "1 / 1",
                background: "transparent",
                overflow: "visible",
                ...style,
            }}
            onPointerEnter={() => setIsHovered(true)}
            onPointerLeave={() => setIsHovered(false)}
        >
            <style>{`
                @keyframes ${outerKeyframes} {
                    from { transform: rotate(0deg); }
                    to { transform: rotate(360deg); }
                }

                @keyframes ${innerKeyframes} {
                    from { transform: rotate(0deg); }
                    to { transform: rotate(-360deg); }
                }

                ${selector} .travingat-badge-artwork > svg {
                    position: absolute;
                    inset: 0;
                    width: 100%;
                    height: 100%;
                    display: block;
                    overflow: visible;
                }
                
                ${selector} .travingat-badge-artwork foreignObject {
                    display: none;
                }

                ${selector} .travingat-badge-artwork .outer-spin {
                    transform-box: view-box;
                    transform-origin: 102.5px 102.5px;
                    animation: ${outerAnimation};
                    animation-play-state: ${playState};
                    will-change: ${outerRotationEnabled ? "transform" : "auto"};
                }

                ${selector} .travingat-badge-artwork .inner-spin {
                    transform-box: view-box;
                    transform-origin: 102.5px 102.5px;
                    animation: ${innerAnimation};
                    animation-play-state: ${playState};
                    will-change: ${innerRotationEnabled ? "transform" : "auto"};
                }

                @media (prefers-reduced-motion: reduce) {
                    ${selector} .travingat-badge-artwork > svg * {
                        animation: none !important;
                        transform: none !important;
                    }
                }
            `}</style>

            <div
                aria-hidden="true"
                style={{
                    position: "absolute",
                    left: "13.376%",
                    top: "13.376%",
                    width: "73.171%",
                    height: "73.171%",
                    display: "block",
                    borderRadius: "50%",
                    backgroundColor: colorWithOpacity(glassTint, glassOpacity),
                    backdropFilter: `blur(${Math.max(0, blurAmount)}px)`,
                    WebkitBackdropFilter: `blur(${Math.max(0, blurAmount)}px)`,
                    pointerEvents: "none",
                }}
            />

            <div
                className="travingat-badge-artwork"
                aria-hidden="true"
                style={{
                    position: "absolute",
                    inset: 0,
                    width: "100%",
                    height: "100%",
                    display: "block",
                    pointerEvents: "none",
                }}
                dangerouslySetInnerHTML={{ __html: BADGE_SVG }}
            />
        </div>
    )
}

TravingatBadge.defaultProps = {
    outerRotationDuration: 18,
    innerRotationDuration: 10,
    outerRotationEnabled: true,
    innerRotationEnabled: true,
    startOnHoverOnly: false,
    blurAmount: 14,
    glassTint: "#080A0F",
    glassOpacity: 0.18,
}

